func permute(nums []int) [][]int {
	n := len(nums)
	res := [][]int{}
	var backtrack func(first int)
	backtrack = func(first int) {
		// 所有数都填完了
		if first == n {
			tmp := make([]int, n)
			copy(tmp, nums)
			res = append(res, tmp)
			return
		}
		for i := first; i < n; i++ {
			// 动态维护数组
			nums[first], nums[i] = nums[i], nums[first]
			// 继续递归填下一个数
			backtrack(first + 1)
			// 撤销操作
			nums[first], nums[i] = nums[i], nums[first]
		}
	}
	backtrack(0)
	return res
}
